awk -v file="$f" '
  /^## /                  { seen = 0; next }
  /^#/                    { next }
  /^[[:space:]]*$/        { next }
  /^- \*\*L[0-9]+\./      { seen = 1; next }
  /^[ \t]/                { next }
  seen == 1               { printf "%s:%d:%s\n", file, NR, substr($0, 1, 80) }
' "$1/$f" 2>/dev/null

LC_ALL=C awk -F'\t' '
   function bad(why) { if (kind != "bad") { kind = "bad"; detail = why } }
   function classify(t,    body, m, targets, parts, np, p, x, reason, words) {
     if (t ~ /^NO CHECK:/) {
       reason = t; sub(/^NO CHECK:[[:space:]]*/, "", reason)
       words = split(reason, x, /[[:space:]]+/)
       if (words < 3) { bad("has a NO CHECK: line giving no reason, and it should read NO CHECK: <why no check can hold it>"); return }
       kind = "nocheck"; detail = reason; return
     }
     if (t ~ /^CHECK:/) {
       body = t; sub(/^CHECK:[[:space:]]*/, "", body)
       if (match(body, /\((full|partial)\)$/) == 0) { bad("has a CHECK: line ending in neither (full) nor (partial), and it should read CHECK: <path> (full) or CHECK: <path> (partial)"); return }
       m = substr(body, RSTART + 1, RLENGTH - 2)
       targets = substr(body, 1, RSTART - 1); sub(/[[:space:]]+$/, "", targets)
       if (targets == "") { bad("has a CHECK: line naming no check, and it should read CHECK: <path> (full) or CHECK: <path> (partial)"); return }
       np = split(targets, parts, /,[[:space:]]*/)
       detail = ""
       for (p = 1; p <= np; p++) {
         x = parts[p]
         if (x ~ /^[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+:[A-Za-z0-9._\/-]+$/) { detail = detail (detail == "" ? "" : " ") x; continue }
         if (x ~ /^[A-Za-z0-9._][A-Za-z0-9._\/-]*$/ && x !~ /(^|\/)\.\.(\/|$)/) { detail = detail (detail == "" ? "" : " ") x; continue }
         bad("names " x " as its check, which is neither a path relative to the config root (hooks/x.sh) nor owner/repo:path"); return
       }
       kind = m; return
     }
     bad("has a line reading " substr(t, 1, 24) " which is in neither shape, and it should read CHECK: <path> (full) or (partial), or NO CHECK: <why no check can hold it>")
   }
   function flush() {
     if (cur == "") return
     if (n == 0) { printf "%s\tneither\t\n", cur; return }
     if (n > 1) { printf "%s\tbad\tcarries %d check lines, and an entry carries one, either CHECK: or NO CHECK:\n", cur, n; return }
     printf "%s\t%s\t%s\n", cur, kind, detail
   }
   $1 == "ENTRY" { flush(); cur = $2; n = 0; kind = ""; detail = ""; next }
   $1 == "CHECKLINE" {
     n++
     if ($3 == 1) { bad("has a check line inside the rule sentence, where the index joins it into the rule, and it belongs after the sentence closes"); next }
     if ($4 == "wrapped") { bad("has a check line running on to the next line, which nothing reads as part of it, and a check line is one line placed just before the SHORT: line or last in the entry"); next }
     if ($4 != "") { bad("has a check line holding a " $4 " inside it, and a check line holds no tab or other control character, since the text past one goes unread or shows other than it was written"); next }
     if (n == 1) classify($5)
   }
   END { flush() }'

