awk -v mode="$2" -v newline="${3:-}" '
  function bare_of(s,   b) {
    b = s
    gsub(/"([^"\\]|\\.)*"/, "", b); gsub(/\047[^\047]*\047/, "", b); sub(/#.*/, "", b)
    return b
  }
  function values_of(s,   t) {
    while (match(s, /"[^"]*"|\047[^\047]*\047|#/)) {
      t = substr(s, RSTART, RLENGTH)
      if (t == "#") return
      print substr(t, 2, length(t) - 2)
      s = substr(s, RSTART + RLENGTH)
    }
  }
  BEGIN { sec = ""; depth = 0; grab = 0; found = 0; bad = 0; hooks_seen = 0; lastblank = 1; any = 0 }
  {
    line = $0; b = bare_of(line); any = 1
    if (depth == 0 && !grab) {
      if (b ~ /^[ \t]*\[\[/) { sec = "[[]]"; if (mode != "read") print line; lastblank = 0; next }
      if (b ~ /^[ \t]*\[/) {
        h = b; sub(/^[ \t]*\[[ \t]*/, "", h); sub(/[ \t]*\][ \t]*$/, "", h); sec = h
        if (sec == "hooks") hooks_seen++
        if (mode != "read") print line
        if (sec == "hooks" && mode == "insert" && hooks_seen == 1) print newline
        lastblank = 0
        next
      }
      if (sec == "" && b ~ /^[ \t]*"?hooks"?[ \t]*(\.|=)/) bad = 1
      if (sec == "hooks" && b ~ /^[ \t]*exclude_commands[ \t]*=/) {
        found++; grab = 1
        if (mode == "replace") print newline
      }
    }
    if (grab && mode == "read") values_of(line)
    if (!grab && mode != "read") print line
    o = gsub(/\[/, "[", b); c = gsub(/\]/, "]", b); depth += o - c
    if (depth <= 0) { depth = 0; grab = 0 }
    lastblank = (line ~ /^[ \t]*$/)
  }
  END {
    if (mode == "append") { if (any && !lastblank) print ""; print "[hooks]"; print newline }
    if (bad || found > 1 || hooks_seen > 1) exit 4
    if (found) exit 0
    if (hooks_seen) exit 3
    exit 5
  }' "$1"

